-- ROMS: align order and order item status CHECK constraints with approved workflow.
-- Prerequisite: verify this version number is unused and V1 is applied.
-- PostgreSQL CHECK constraints generated by unnamed CREATE TABLE checks in V1.

-- Fail explicitly if old REJECTED orders exist. Their disposition requires
-- a business decision; this migration must not silently rewrite history.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM orders WHERE status = 'REJECTED') THEN
        RAISE EXCEPTION 'Cannot apply V2: orders with REJECTED status exist; resolve data before migration';
    END IF;
END $$;

ALTER TABLE orders DROP CONSTRAINT orders_status_check;
ALTER TABLE orders ADD CONSTRAINT orders_status_check
    CHECK (status IN ('PENDING', 'COOKING', 'COMPLETED', 'CANCELLED'));

ALTER TABLE order_items DROP CONSTRAINT order_items_status_check;
ALTER TABLE order_items ADD CONSTRAINT order_items_status_check
    CHECK (status IN ('PENDING', 'COOKING', 'READY', 'COMPLETED', 'CANCELLED'));
